  // Helper to set visible window (x-axis min/max) based on candle limit and pan position
  const setVisibleWindow = (chart, candles, candleLimit) => {
    if (!chart || !candles.length) return;
    // If user has panned, preserve their min/max; otherwise, show the most recent candles
    const scale = chart.scales.x;
    // If the user hasn't panned (min/max undefined or at right edge), snap to most recent
    if (!scale.min || scale.max >= candles[candles.length - 1].x) {
      const visibleCandles = candles.slice(-candleLimit);
      const min = visibleCandles[0]?.x;
      const max = visibleCandles[visibleCandles.length - 1]?.x;
      if (min && max) {
        chart.options.scales.x.min = min;
        chart.options.scales.x.max = max;
      }
    }
    // If the user has panned, keep their view (do not override min/max)
  };

