  // Pan handler for Chart.js zoom plugin
  const handlePanComplete = ({ chart }) => {
    if (!chart) return;
    // Get leftmost visible timestamp
    const min = chart.scales.x.min;
    const candles = candlesRef.current;
    if (!candles.length) return;
    
    // Calculate preload threshold based on timeframe
    let preloadThreshold = 2; // Default: preload when within 100 candles
    if (internalTimeframe === "1d" || internalTimeframe === "1w")
      preloadThreshold = 5;
    else if (internalTimeframe === "1h") preloadThreshold = 8;
    else if (internalTimeframe === "15m") preloadThreshold = 12;
    else if (internalTimeframe === "5m") preloadThreshold = 15;
    else preloadThreshold = 20; // 1m timeframe: preload when within 20 candles
    
    // If user is within preloadThreshold candles of the earliest loaded, fetch more
    if (min <= candles[preloadThreshold]?.x) {
      fetchMoreHistoricalData();
    }
  };

