  // Selection and deletion (basic)
  function handleChartClick(e) {
    if (!chartInstance.current || !showDrawTools) return;
    const chart = chartInstance.current;
    const { x, y } = getDataCoords(e, chart);
    // Hit test: select nearest drawing (trend/arrow/rect only for now)
    let found = null;
    for (const d of drawings) {
      if (d.type === "trend" || d.type === "arrow") {
        // Distance from point to line segment
        const x1 = d.x1,
          y1 = d.y1,
          x2 = d.x2,
          y2 = d.y2;
        const A = x - x1,
          B = y - y1,
          C = x2 - x1,
          D = y2 - y1;
        const dot = A * C + B * D;
        const len_sq = C * C + D * D;
        let param = -1;
        if (len_sq !== 0) param = dot / len_sq;
        let xx, yy;
        if (param < 0) {
          xx = x1;
          yy = y1;
        } else if (param > 1) {
          xx = x2;
          yy = y2;
        } else {
          xx = x1 + param * C;
          yy = y1 + param * D;
        }
        const dist = Math.sqrt((x - xx) ** 2 + (y - yy) ** 2);
        if (dist < 0.5) {
          found = d.id;
          break;
        }
      } else if (d.type === "rect") {
        const minX = Math.min(d.x1, d.x2),
          maxX = Math.max(d.x1, d.x2);
        const minY = Math.min(d.y1, d.y2),
          maxY = Math.max(d.y1, d.y2);
        if (x >= minX && x <= maxX && y >= minY && y <= maxY) {
          found = d.id;
          break;
        }
      } else if (d.type === "hline") {
        if (Math.abs(y - d.y) < 0.5) {
          found = d.id;
          break;
        }
      } else if (d.type === "vline") {
        if (Math.abs(x - d.x) < 0.5) {
          found = d.id;
          break;
        }
      }
    }
    setSelectedId(found);
  }

