  // --- Moving Average Calculation ---
  useEffect(() => {
    if (
      !showMovingAverage ||
      !candlesRef.current ||
      candlesRef.current.length === 0
    ) {
      setMaData([]);
      return;
    }
    const candles = candlesRef.current;
    const period = Math.max(2, Math.min(200, maPeriod));
    let ma = [];
    if (maType === "SMA") {
      // Simple Moving Average
      for (let i = 0; i < candles.length; i++) {
        if (i < period - 1) {
          ma.push({ x: candles[i].x, y: null });
        } else {
          let sum = 0;
          for (let j = i - period + 1; j <= i; j++) {
            sum += candles[j].c;
          }
          ma.push({ x: candles[i].x, y: sum / period });
        }
      }
    } else if (maType === "EMA") {
      // Exponential Moving Average
      let k = 2 / (period + 1);
      let prev = candles[0].c;
      for (let i = 0; i < candles.length; i++) {
        let val = candles[i].c;
        if (i === 0) {
          ma.push({ x: candles[i].x, y: val });
        } else if (i < period - 1) {
          // Not enough data for full EMA, use SMA up to this point
          let sum = 0;
          for (let j = 0; j <= i; j++) sum += candles[j].c;
          ma.push({ x: candles[i].x, y: sum / (i + 1) });
          prev = sum / (i + 1);
        } else {
          let ema = val * k + prev * (1 - k);
          ma.push({ x: candles[i].x, y: ema });
          prev = ema;
        }
      }
    }
    setMaData(ma);
  }, [showMovingAverage, maPeriod, maType, candlesRef.current]);

