  // Add state for Bollinger Bands settings
  const [showBollingerBands, setShowBollingerBands] = useState(false);
  const [bbPeriod, setBbPeriod] = useState(20);
  const [bbStdDev, setBbStdDev] = useState(2);
  const [bbData, setBbData] = useState({ upper: [], middle: [], lower: [] });

  // --- Bollinger Bands Calculation ---
  useEffect(() => {
    if (
      !showBollingerBands ||
      !candlesRef.current ||
      candlesRef.current.length === 0
    ) {
      setBbData({ upper: [], middle: [], lower: [] });
      return;
    }
    const candles = candlesRef.current;
    const period = Math.max(2, Math.min(200, bbPeriod));
    const stdDev = Math.max(1, Math.min(5, bbStdDev));
    let upper = [],
      middle = [],
      lower = [];
    for (let i = 0; i < candles.length; i++) {
      if (i < period - 1) {
        upper.push({ x: candles[i].x, y: null });
        middle.push({ x: candles[i].x, y: null });
        lower.push({ x: candles[i].x, y: null });
      } else {
        // SMA
        let sum = 0;
        for (let j = i - period + 1; j <= i; j++) {
          sum += candles[j].c;
        }
        let sma = sum / period;
        // Std Dev
        let variance = 0;
        for (let j = i - period + 1; j <= i; j++) {
          variance += Math.pow(candles[j].c - sma, 2);
        }
        let stdev = Math.sqrt(variance / period);
        upper.push({ x: candles[i].x, y: sma + stdDev * stdev });
        middle.push({ x: candles[i].x, y: sma });
        lower.push({ x: candles[i].x, y: sma - stdDev * stdev });
      }
    }
    setBbData({ upper, middle, lower });
  }, [showBollingerBands, bbPeriod, bbStdDev, candlesRef.current]);

