import React, { useEffect, useState, useRef } from "react";
import { FaArrowRight } from 'react-icons/fa';
import { FaCog } from 'react-icons/fa';
import { FaInfoCircle } from 'react-icons/fa';
import {
  postRequest,
  getCashAvailable,
  getBalance,
} from "../utility/config";

const COLOR_BUY = '#66b566';
const COLOR_SELL = '#f46969';
const SOFT_COLOR_BUY = '#2e7d32'; // deep green
const SOFT_COLOR_SELL = '#c62828'; // deep red

const PlaceOrder = ({ orderType, hidePlaceOrder, placeOrderTokenId, placeOrderRect, placeOrderSym }) => {
  const [quantity, setQuantity] = useState(1);
  const [limitPrice, setLimitPrice] = useState(0);
  const [cashBalance, setCashBalance] = useState(getCashAvailable());
  const [orderValue, setOrderValue] = useState(0);
  const [data, setData] = useState({});
  const userToken = localStorage.getItem("kite-userToken");
  const [ltp, setLtp] = useState(0);
  const popupRef = useRef(null);
  const [productType, setProductType] = useState('CNC'); // 'CNC' for Delivery, 'MIS' for Intraday
  const [orderTypeChoice, setOrderTypeChoice] = useState('LIMIT'); // 'LIMIT' or 'MARKET'
  const [showSettings, setShowSettings] = useState(false);
  const [savePrefs, setSavePrefs] = useState(() => {
    const saved = localStorage.getItem('saveOrderPrefs');
    return saved === null ? true : saved === 'true';
  });
  const [saveProductType, setSaveProductType] = useState(() => {
    const saved = localStorage.getItem('saveProductTypePref');
    return saved === null ? true : saved === 'true';
  });
  const [useDefaultQty, setUseDefaultQty] = useState(() => {
    const saved = localStorage.getItem('useDefaultQty');
    return saved === null ? false : saved === 'true';
  });
  const [defaultQty, setDefaultQty] = useState(() => {
    const saved = localStorage.getItem('defaultQtyMap');
    if (saved) {
      try {
        const map = JSON.parse(saved);
        return map[placeOrderTokenId] || 1;
      } catch {}
    }
    return 1;
  });
  const settingsRef = useRef();
  const settingsIconRef = useRef();
  const [isMobile, setIsMobile] = useState(false);
  const [swipeProgress, setSwipeProgress] = useState(0);
  const [isSwiping, setIsSwiping] = useState(false);
  const swipeTrackRef = useRef(null);
  const swipeThumbRef = useRef(null);

  // --- Zerodha Fees Calculation ---
  const [fees, setFees] = useState({
    total: 0,
    stt: 0,
    txn: 0,
    gst: 0,
    sebi: 0,
    stamp: 0,
    brokerage: 0,
  });
  const [showFeesTooltip, setShowFeesTooltip] = useState(false);
  const feesTooltipRef = useRef();
  const feesIconRef = useRef();

  // Close fees tooltip on outside click
  useEffect(() => {
    if (!showFeesTooltip) return;
    function handleClick(e) {
      if (
        feesTooltipRef.current &&
        !feesTooltipRef.current.contains(e.target) &&
        feesIconRef.current &&
        !feesIconRef.current.contains(e.target)
      ) {
        setShowFeesTooltip(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showFeesTooltip]);

useEffect(() => {
  function calcFees({ qty, price, productType, orderType }) {
    qty = Number(qty);
    price = Number(price);
    if (!qty || !price) {
      return {
        total: 0,
        brokerage: 0,
        stt: 0,
        txn: 0,
        gst: 0,
        sebi: 0,
        stamp: 0,
        dp: 0,
      };
    }

    // For estimation, assume buy and sell at same price if only one price is available
    const buyValue = qty * price;
    const sellValue = qty * price;
    let brokerage = 0,
      stt = 0,
      txn = 0,
      gst = 0,
      sebi = 0,
      stamp = 0,
      dp = 0;

    if (productType === "CNC") {
      // Equity Delivery (NSE)
      brokerage = 0;
      // STT: 0.1% on buy, 0.1% on sell
      if (orderType === "buy") {
        stt = 0.001 * buyValue;
        txn = 0.0000297 * buyValue;
        sebi = 0.000001 * buyValue;
        stamp = 0.00015 * buyValue;
      } else if (orderType === "sell") {
        stt = 0.001 * sellValue;
        txn = 0.0000297 * sellValue;
        sebi = 0.000001 * sellValue;
        stamp = 0;
        dp = 13.5 * 1.18; // ₹13.5 + 18% GST = ₹15.93
      }
    } else {
      // Equity Intraday (NSE)
      // Brokerage: 0.03% of order value, max ₹20 per executed order
      if (orderType === "buy") {
        brokerage = Math.min(0.0003 * buyValue, 20);
        stt = 0;
        txn = 0.0000297 * buyValue;
        sebi = 0.000001 * buyValue;
        stamp = 0.00003 * buyValue;
      } else if (orderType === "sell") {
        brokerage = Math.min(0.0003 * sellValue, 20);
        stt = 0.00025 * sellValue;
        txn = 0.0000297 * sellValue;
        sebi = 0.000001 * sellValue;
        stamp = 0;
      }
      dp = 0;
    }

    // GST: 18% on (brokerage + txn) for the current leg
    gst = 0.18 * (brokerage + txn);
    const total = brokerage + stt + txn + gst + sebi + stamp + dp;

    return {
      total,
      brokerage,
      stt,
      txn,
      gst,
      sebi,
      stamp,
      dp,
    };
  }

  setFees(
    calcFees({ qty: quantity, price: limitPrice, productType, orderType })
  );
}, [quantity, limitPrice, productType, orderType]);



  useEffect(() => {
    setIsMobile(window.innerWidth < 500);
  }, []);

  useEffect(() => {
    if (popupRef.current) {
      if (window.innerWidth < 500) {
        // Mobile: center modal, use fixed position
        popupRef.current.style.position = 'fixed';
        popupRef.current.style.left = '50%';
        popupRef.current.style.top = '50%';
        popupRef.current.style.transform = 'translate(-50%, -50%)';
        popupRef.current.style.width = '95vw';
        popupRef.current.style.maxWidth = '290px';
        popupRef.current.style.minWidth = '0';
        popupRef.current.style.minHeight = '0';
        popupRef.current.style.height = 'auto';
        popupRef.current.style.padding = '16px 10px 12px 10px';
      } else {
        // Desktop: anchor to tag, clamp to viewport
        popupRef.current.style.position = 'absolute';
        let left = placeOrderRect.left - 20;
        let top = placeOrderRect.top - 140 + window.scrollY;
        // Clamp left to viewport
        left = Math.max(10, Math.min(left, window.innerWidth - 270));
        // Clamp top to viewport
        top = Math.max(10, Math.min(top, window.innerHeight - 270 + window.scrollY));

        // Center horizontally in left component if not already centered
        const leftComponent = document.getElementById('left-components');
        if (leftComponent && popupRef.current) {
          const leftRect = leftComponent.getBoundingClientRect();
          const popupWidth = popupRef.current.offsetWidth || 220;
          const centerLeft = leftRect.left + (leftRect.width - popupWidth) / 2;
          // If the default left is outside the left component or not centered, center it
          if (left < leftRect.left || left + popupWidth > leftRect.right || Math.abs(left - centerLeft) > 20) {
            left = centerLeft;
          }
        }

        popupRef.current.style.left = `${left}px`;
        popupRef.current.style.top = `${top}px`;
        popupRef.current.style.transform = '';
        popupRef.current.style.width = '270px';
        popupRef.current.style.maxWidth = '270px';
        popupRef.current.style.minWidth = '0';
        popupRef.current.style.minHeight = '0';
        popupRef.current.style.height = 'auto';
        popupRef.current.style.padding = '16px 10px 12px 10px';
      }
    }
  }, [placeOrderRect]);

  useEffect(() => {
    const tag = document.getElementById("order-"+placeOrderTokenId);
    if (tag) {
      let price = tag.querySelector("div span:nth-child(2)").textContent;
      setData({symname: tag.querySelector("div span:nth-child(1)").textContent.split(":")[0]});
      setLtp(price);
      setLimitPrice(calculateInitialPrice(price || 0));
    }
  }, [placeOrderTokenId]);

  useEffect(() => {
    setOrderValue((quantity * limitPrice).toFixed(2));
  }, [quantity, limitPrice]);

  // Remember user choice for productType and orderType
  useEffect(() => {
    // Try to load from localStorage
    const saved = localStorage.getItem('orderPrefs');
    if (saved) {
      try {
        const prefs = JSON.parse(saved);
        if (prefs[productType]) {
          setOrderTypeChoice(prefs[productType].orderType || 'LIMIT');
        } else {
          setOrderTypeChoice('LIMIT');
        }
      } catch {}
    } else {
      setOrderTypeChoice('LIMIT');
    }
  }, [productType]);

  // Only save preferences if savePrefs/saveProductType is true
  useEffect(() => {
    if (savePrefs || saveProductType) {
      const saved = localStorage.getItem('orderPrefs');
      let prefs = {};
      if (saved) {
        try { prefs = JSON.parse(saved); } catch {}
      }
      if (savePrefs) {
        prefs[productType] = { orderType: orderTypeChoice };
      }
      if (saveProductType) {
        prefs.lastProductType = productType;
      }
      localStorage.setItem('orderPrefs', JSON.stringify(prefs));
    }
  }, [productType, orderTypeChoice, savePrefs, saveProductType]);
  useEffect(() => {
    localStorage.setItem('saveProductTypePref', saveProductType);
  }, [saveProductType]);
  // On mount, restore productType if saved
  useEffect(() => {
    const saved = localStorage.getItem('orderPrefs');
    if (saved) {
      try {
        const prefs = JSON.parse(saved);
        if (prefs.lastProductType && saveProductType) {
          setProductType(prefs.lastProductType);
        }
      } catch {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('saveOrderPrefs', savePrefs);
  }, [savePrefs]);

  // Set quantity to default when enabled or token changes
  useEffect(() => {
    if (useDefaultQty) {
      setQuantity(defaultQty);
    }
    // eslint-disable-next-line
  }, [useDefaultQty, placeOrderTokenId]);

  // Save default quantity per token
  useEffect(() => {
    if (useDefaultQty) {
      const saved = localStorage.getItem('defaultQtyMap');
      let map = {};
      if (saved) {
        try { map = JSON.parse(saved); } catch {}
      }
      map[placeOrderTokenId] = defaultQty;
      localStorage.setItem('defaultQtyMap', JSON.stringify(map));
    }
    localStorage.setItem('useDefaultQty', useDefaultQty);
  }, [useDefaultQty, defaultQty, placeOrderTokenId]);

  // Close settings menu on outside click
  useEffect(() => {
    if (!showSettings) return;
    function handleClick(e) {
      if (
        settingsRef.current &&
        !settingsRef.current.contains(e.target) &&
        settingsIconRef.current &&
        !settingsIconRef.current.contains(e.target)
      ) {
        setShowSettings(false);
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [showSettings]);

  function calculateInitialPrice(data) {
    let curPrice = parseFloat(data);
    curPrice += orderType === "buy" ? -(curPrice / 300) : curPrice / 300;
    return curPrice.toFixed(1);
  }

  // Swipe-to-buy/sell handlers
  const handleSwipeStart = (e) => {
    setIsSwiping(true);
    document.body.style.userSelect = 'none';
  };

  const handleSwipeMove = (e) => {
    if (!isSwiping) return;
    let clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const track = swipeTrackRef.current;
    if (!track) return;
    const rect = track.getBoundingClientRect();
    let progress = (clientX - rect.left) / rect.width;
    progress = Math.max(0, Math.min(1, progress));
    setSwipeProgress(progress);
  };

  const handleSwipeEnd = async (e) => {
    setIsSwiping(false);
    document.body.style.userSelect = '';
    // Calculate the effective threshold based on the 2px offset
    const track = swipeTrackRef.current;
    let effectiveThreshold = 0.92;
    if (track) {
      const rect = track.getBoundingClientRect();
      effectiveThreshold = (rect.width - 2) / rect.width;
    }
    if (swipeProgress > effectiveThreshold) {
      setSwipeProgress(1);
      // Trigger order submit
      await handleSubmit(e, true);
      setTimeout(() => setSwipeProgress(0), 600);
    } else {
      setSwipeProgress(0);
    }
  };

  // Modified handleSubmit to allow swipe
  const handleSubmit = async (event, fromSwipe = false) => {
    if (!fromSwipe) event.preventDefault();
    // if (
    //   orderType === "buy" &&
    //   parseFloat(quantity) * parseFloat(limitPrice) >
    //     parseFloat(getCashAvailable())
    // ) {
    //   alert("Warning: Order value exceeds cash balance!");
    //   return;
    // }

    const newOrderType = orderType === "buy" ? "BUY" : "SELL";
    const jData = {
      variety: "regular",
      transaction_type: newOrderType,
      exchange: "NSE",
      tradingsymbol: placeOrderSym,
      quantity: quantity.toString(),
      order_type: orderTypeChoice,
      product: productType,
      price: orderTypeChoice === 'MARKET' ? "0" : limitPrice.toString(),
      token: userToken,
    };

    try {
      const res = await postRequest("placeorder", jData);
      const msgElement = document.getElementById("msg");
      if (res && res.data && res.data.status && res.data.status === "success") {
        hidePlaceOrder();
        msgElement.innerHTML = "Order placed";
        msgElement.style.opacity = "1";
        setTimeout(() => {
          msgElement.style.opacity = "1";
        }, 1500);
        setTimeout(() => {
          msgElement.style.opacity = "0";
        }, 1500);
        getBalance(userToken);
      } else {
        msgElement.innerHTML = "Could not place order...";
        msgElement.style.backgroundColor = "#e88888";
        msgElement.style.opacity = "1";
        setTimeout(() => {
          msgElement.style.opacity = "1";
        }, 1500);
        setTimeout(() => {
          msgElement.style.opacity = "0";
        }, 1500);
      }
    } catch (err) {
      console.log(err);
    }
  };

  // Calculate swipe thumb left position (clamped)
  const getSwipeThumbLeft = () => {
    const thumbWidth = 40;
    const offset = 2;
    const track = swipeTrackRef.current;
    if (track) {
      const rect = track.getBoundingClientRect();
      const maxLeft = rect.width - thumbWidth - offset;
      const left = swipeProgress * rect.width - thumbWidth * swipeProgress + offset;
      return `${Math.min(left, maxLeft)}px`;
    }
    // fallback
    return `calc(${swipeProgress * 100}% - 20px * ${swipeProgress} + 2px)`;
  };

  return (
    <>
      <style>{`
        .swipe-shimmer {
          background: linear-gradient(90deg, rgba(255,255,255,0.08) 0%, rgba(255,255,255,0.55) 50%, rgba(255,255,255,0.08) 100%);
          background-size: 200% 100%;
          background-position: 200% 0;
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          animation: shimmerSwipe 2.8s linear infinite;
        }
        @keyframes shimmerSwipe {
          0% { background-position: 200% 0; }
          100% { background-position: -200% 0; }
        }
      `}</style>
      <div
        className="place-order-list" id="place-order-list" ref={popupRef}
        style={{
          minWidth: '200px',
          maxWidth: '220px',
          width: '220px',
          ...(isMobile
            ? {}
            : {
                display: 'flex',
                flexDirection: 'row',
                alignItems: 'center',
                alignContent: 'center',
                marginLeft: 'auto',
                marginRight: 'auto',
                display: 'block',
              }),
        }}
      >
        <button
          id="close-order-form"
          onClick={hidePlaceOrder}
          tabIndex={0}
          aria-label="Close order form"
          type="button"
          style={{
            position: "absolute",
            top: 15,
            right: -5,
            zIndex: 20,
            background: "none",
            border: "none",
            color: "red",
            fontSize: 25,
            width: 36,
            height: 36,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: "pointer",
            borderRadius: 4,
            transition: "background 0.18s, color 0.18s",
          }}
        >
          <span style={{ fontSize: 30, fontWeight: 700, lineHeight: 1 }}>
            ×
          </span>
        </button>
        <div
          className="order-header"
          style={{
            color: orderType === "buy" ? COLOR_BUY : COLOR_SELL,
          }}
        >
          {orderType === "buy" ? "Buy" : "Sell"} {data.symname}{" "}
          <span style={{ fontWeight: 400, fontSize: "0.95em" }}>
            LTP: {ltp}
          </span>
        </div>
        <div className="order-divider" />
        <div
          style={{
            width: "100%",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            position: "relative",
            marginBottom: 2,
          }}
        >
          <div style={{ color: '#b0b8c1', fontSize: 12, lineHeight: 1.3, display: 'flex', alignItems: 'center', gap: 6, position: 'relative' }}>
            Fees: ₹{fees.total.toFixed(2)}
            <span
              ref={feesIconRef}
              style={{ cursor: 'pointer', color: '#8fa1b8', display: 'inline-flex', alignItems: 'center' }}
              onClick={() => setShowFeesTooltip(s => !s)}
              title="Show fees breakdown"
            >
              <FaInfoCircle size={14} />
            </span>
            {showFeesTooltip && (
              <div
                ref={feesTooltipRef}
                style={{
                  position: 'absolute',
                  top: 22,
                  left: 0,
                  minWidth: 210,
                  background: '#23263a',
                  color: '#b0b8c1',
                  border: '1px solid #2e2e44',
                  borderRadius: 7,
                  boxShadow: '0 4px 16px #0007',
                  fontSize: 12,
                  padding: '10px 12px',
                  zIndex: 10000,
                  whiteSpace: 'normal',
                }}
              >
                <div style={{ fontWeight: 700, marginBottom: 4 }}>Fees Breakdown</div>
                <div>Brokerage: ₹{fees.brokerage.toFixed(2)}</div>
                <div>STT: ₹{fees.stt.toFixed(2)}</div>
                <div>Transaction: ₹{fees.txn.toFixed(2)}</div>
                <div>GST: ₹{fees.gst.toFixed(2)}</div>
                <div>SEBI: ₹{fees.sebi.toFixed(2)}</div>
                <div>Stamp: ₹{fees.stamp.toFixed(2)}</div>
                {fees.dp > 0 && <div>DP: ₹{fees.dp.toFixed(2)}</div>}
              </div>
            )}
          </div>
          <span
            ref={settingsIconRef}
            style={{
              cursor: "pointer",
              color: "#b0b8c1",
              zIndex: 10,
              marginRight: 2,
            }}
            onClick={() => setShowSettings((s) => !s)}
          >
            <FaCog size={18} />
          </span>
          {showSettings && (
            <div
              ref={settingsRef}
              style={{
                position: "absolute",
                top: 28,
                right: 0,
                zIndex: 9999,
                width: 260,
                background: "#181927",
                border: "1px solid #2e2e44",
                borderRadius: 8,
                padding: "14px 14px 12px 14px",
                boxShadow: "0 6px 24px #0007",
                color: "#b0b8c1",
                fontSize: 13,
                display: "flex",
                flexDirection: "column",
                alignItems: "flex-start",
                gap: 10,
              }}
            >
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontWeight: 600 }}>
                <input
                  type="checkbox"
                  checked={savePrefs}
                  onChange={(e) => setSavePrefs(e.target.checked)}
                  style={{ accentColor: "#2e7d32", marginRight: 4 }}
                />
                Save order type preference
              </label>
              <label style={{ display: "flex", alignItems: "center", gap: 6, fontWeight: 600 }}>
                <input
                  type="checkbox"
                  checked={saveProductType}
                  onChange={(e) => setSaveProductType(e.target.checked)}
                  style={{ accentColor: "#2e7d32", marginRight: 4 }}
                />
                Delivery/Intraday preference
              </label>
              <div style={{ display: "flex", alignItems: "center", gap: 8, width: "100%" }}>
                <input
                  type="checkbox"
                  checked={useDefaultQty}
                  onChange={e => setUseDefaultQty(e.target.checked)}
                  style={{ accentColor: "#2e7d32", marginRight: 4 }}
                  id="use-default-qty"
                />
                <label htmlFor="use-default-qty" style={{ fontWeight: 600, flex: 1 }}>
                  Default quantity
                </label>
                <input
                  type="number"
                  min={1}
                  value={defaultQty}
                  onChange={e => setDefaultQty(Math.max(1, e.target.value))}
                  style={{ width: 70, fontSize: 13, borderRadius: 4, border: '1px solid #2e7d32', background: '#23263a', color: '#b0b8c1', padding: '2px 6px', marginLeft: 2, marginBottom: "0" }}
                  disabled={!useDefaultQty}
                />
              </div>
            </div>
          )}
        </div>
        <form
          id="place-order-form"
          onSubmit={handleSubmit}
          style={{ width: "100%" }}
        >
          <div style={{ display: 'flex', justifyContent: 'center', gap: 6, marginBottom: 10, marginTop: 10, width: '100%' }}>
            {/* Product Type Tabs */}
            <div style={{ display: 'flex', borderRadius: 6, background: '#23263a', border: '1px solid #2e2e44', overflow: 'hidden', marginRight: 2 }}>
              <button
                type="button"
                onClick={() => setProductType('CNC')}
                style={{
                  background: productType === 'CNC' ? '#2e7d32' : 'transparent',
                  color: productType === 'CNC' ? '#fff' : '#b0b8c1',
                  fontWeight: 700,
                  fontSize: isMobile ? 11 : 12,
                  border: 'none',
                  padding: '5px 10px',
                  cursor: 'pointer',
                  outline: 'none',
                  borderRight: '1px solid #2e2e44',
                  transition: 'background 0.18s',
                }}
              >
                Delivery
              </button>
              <button
                type="button"
                onClick={() => setProductType('MIS')}
                style={{
                  background: productType === 'MIS' ? '#c62828' : 'transparent',
                  color: productType === 'MIS' ? '#fff' : '#b0b8c1',
                  fontWeight: 700,
                  fontSize: isMobile ? 11 : 12,
                  border: 'none',
                  padding: '5px 10px',
                  cursor: 'pointer',
                  outline: 'none',
                  borderLeft: '1px solid #2e2e44',
                  transition: 'background 0.18s',
                }}
              >
                Intraday
              </button>
            </div>
            {/* Order Type Tabs */}
            <div style={{ display: 'flex', borderRadius: 6, background: '#23263a', border: '1px solid #2e2e44', overflow: 'hidden', marginLeft: 2 }}>
              <button
                type="button"
                onClick={() => setOrderTypeChoice('LIMIT')}
                style={{
                  background: orderTypeChoice === 'LIMIT' ? '#2e7d32' : 'transparent',
                  color: orderTypeChoice === 'LIMIT' ? '#fff' : '#b0b8c1',
                  fontWeight: 700,
                  fontSize: isMobile ? 11 : 12,
                  border: 'none',
                  padding: '5px 10px',
                  cursor: 'pointer',
                  outline: 'none',
                  borderRight: '1px solid #2e2e44',
                  transition: 'background 0.18s',
                }}
              >
                Limit
              </button>
              <button
                type="button"
                onClick={() => setOrderTypeChoice('MARKET')}
                style={{
                  background: orderTypeChoice === 'MARKET' ? '#c62828' : 'transparent',
                  color: orderTypeChoice === 'MARKET' ? '#fff' : '#b0b8c1',
                  fontWeight: 700,
                  fontSize: isMobile ? 11 : 12,
                  border: 'none',
                  padding: '5px 10px',
                  cursor: 'pointer',
                  outline: 'none',
                  borderLeft: '1px solid #2e2e44',
                  transition: 'background 0.18s',
                }}
              >
                Market
              </button>
            </div>
          </div>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginBottom: 4,
            }}
          >
            <span style={{ color: "#b0b8c1" }}>
              Balance: {parseFloat(cashBalance).toFixed(2)}
            </span>
            <span style={{ color: "#b0b8c1" }}>
              Value: {parseFloat(orderValue).toFixed(2)}
            </span>
          </div>
          {/* Quantity */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 0, marginBottom: 8, width: '100%' }}>
            <label htmlFor="quantity" style={{ width: '50%', color: '#b0b8c1', fontWeight: 600, fontSize: 13, marginBottom: 0, textAlign: 'left' }}>Quantity</label>
            <input
              type="number"
              id="quantity"
              name="quantity"
              value={quantity}
              min="1"
              onChange={(e) => setQuantity(e.target.value)}
              style={{ width: '50%', padding: '8px 10px', border: '1.5px solid #353a4a', borderRadius: 6, background: '#181c23', color: '#e0e0e0', fontSize: 15, marginBottom: 0, transition: 'border 0.18s, box-shadow 0.18s', textAlign: 'left' }}
            />
          </div>
          {/* Limit Price */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 0, marginBottom: 8, width: '100%' }}>
            <label htmlFor="limitPrice" style={{ width: '50%', color: '#b0b8c1', fontWeight: 600, fontSize: 13, marginBottom: 0, textAlign: 'left' }}>Limit Price</label>
            <input
              type="number"
              id="limitPrice"
              name="limitPrice"
              value={limitPrice}
              min="0"
              step="0.05"
              onChange={(e) => setLimitPrice(e.target.value)}
              disabled={orderTypeChoice === "MARKET"}
              style={{ width: '50%', padding: '8px 10px', border: orderTypeChoice === 'MARKET' ? '1.5px solid #444' : '1.5px solid #353a4a', borderRadius: 6, background: orderTypeChoice === 'MARKET' ? '#23242a' : '#181c23', color: orderTypeChoice === 'MARKET' ? '#888' : '#e0e0e0', fontSize: 15, marginBottom: 0, transition: 'border 0.18s, box-shadow 0.18s', cursor: orderTypeChoice === 'MARKET' ? 'not-allowed' : 'auto', textAlign: 'left' }}
              placeholder={orderTypeChoice === 'MARKET' ? 'Disabled for Market order' : ''}
              title={orderTypeChoice === 'MARKET' ? 'Price cannot be set for Market order' : ''}
            />
          </div>
          <div className="order-actions">
            {isMobile ? (
              <div
                ref={swipeTrackRef}
                style={{
                  position: "relative",
                  width: "95%",
                  margin: "10px auto",
                  height: 46,
                  background: "#181c23",
                  borderRadius: 25,
                  overflow: "hidden",
                  border: `1.5px solid ${
                    orderType === "buy" ? SOFT_COLOR_BUY : SOFT_COLOR_SELL
                  }`,
                  userSelect: "none",
                  boxShadow: "0 2px 8px #00000022",
                  touchAction: "pan-x",
                }}
                onTouchStart={handleSwipeStart}
                onTouchMove={handleSwipeMove}
                onTouchEnd={handleSwipeEnd}
                onMouseDown={handleSwipeStart}
                onMouseMove={isSwiping ? handleSwipeMove : undefined}
                onMouseUp={handleSwipeEnd}
                onMouseLeave={isSwiping ? handleSwipeEnd : undefined}
              >
                <div
                  ref={swipeThumbRef}
                  style={{
                    position: "absolute",
                    left: getSwipeThumbLeft(),
                    top: '1px',
                    width: 40,
                    height: 40,
                    background:
                      orderType === "buy" ? SOFT_COLOR_BUY : SOFT_COLOR_SELL,
                    borderRadius:'50%',
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 22,
                    cursor: "pointer",
                    transition: isSwiping
                      ? "none"
                      : "left 0.25s cubic-bezier(.4,0,.2,1)",
                    zIndex: 2,
                    userSelect: "none",
                    border: "2px solid #fff",
                  }}
                >
                  <FaArrowRight style={{ fontSize: 18 }} />
                </div>
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    width: "100%",
                    height: "100%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    pointerEvents: "none",
                    color:
                      swipeProgress > 0.5
                        ? "#fff"
                        : orderType === "buy"
                        ? SOFT_COLOR_BUY
                        : SOFT_COLOR_SELL,
                    fontWeight: 700,
                    fontSize: 15,
                    letterSpacing: 1.2,
                    opacity: 0.92,
                    transition: "color 0.18s",
                    zIndex: 1,
                    userSelect: "none",
                  }}
                >
                  {swipeProgress > 0.92 ? (
                    orderType === "buy" ? (
                      "Release to Buy"
                    ) : (
                      "Release to Sell"
                    )
                  ) : (
                    <span className="swipe-shimmer">
                      {orderType === "buy" ? "Swipe to Buy" : "Swipe to Sell"}
                    </span>
                  )}
                </div>
              </div>
            ) : (
              <button type="submit">Submit Order</button>
            )}
          </div>
        </form>
      </div>
    </>
  );
};

export default PlaceOrder;
